<link rel="stylesheet" href="{{ asset('css/messenger.css') }}?v=20261113">
<div class="tm-host"><section class="tm" x-data="textMessenger()" data-user-id="{{ auth()->id() }}" :class="{'tm--chat':mobileChat}" aria-label="پیام‌رسان تعمیرآنلاین" @keydown.escape.window="escape()">
 <aside class="tm-aside" aria-label="فهرست گفتگوها">
  <div class="tm-listhead"><div><h1>پیام‌رسان</h1><span class="tm-caption">گفتگوهای کاری، یک‌جا و مرتب</span></div><div class="tm-headtools"><button class="tm-iconbtn" @click="openStars()" aria-label="پیام‌های ستاره‌دار" :class="{'is-active':view==='stars'}" title="پیام‌های ستاره‌دار" x-html="icon('star')"></button><button class="tm-iconbtn tm-new" @click="showCreate()" aria-label="گفتگوی جدید" title="گفتگوی جدید" x-html="icon('plus')"></button></div></div>
  <label class="tm-search"><span x-html="icon('search')"></span><input x-model="query" placeholder="جستجو در گفتگوها…" aria-label="جستجو در گفتگوها"><button x-show="query" @click="query=''" aria-label="پاک‌کردن جستجو" x-html="icon('close')"></button></label>
  <div class="tm-tabs" role="tablist" aria-label="دسته‌بندی گفتگوها"><template x-for="t in tabs" :key="t.id"><button role="tab" :aria-selected="tab===t.id" @click="tab=t.id" :class="{'is-active':tab===t.id}"><span x-text="t.label"></span><small x-text="tabCount(t.id)"></small></button></template></div>
  <button class="tm-self" @click="openSelf()" :class="{'is-active':current?.type==='saved'&&view==='chat'}" aria-label="بازکردن فضای شخصی"><span class="tm-avatar tm-avatar--saved" x-html="icon('bookmark')"></span><span class="tm-rowtext"><strong>فضای شخصی</strong><span>پیام‌های ذخیره‌شده و یادداشت‌های من</span></span><span class="tm-pin" x-html="icon('pin')" title="همیشه پین‌شده"></span></button>
  <div class="tm-conversations"><template x-for="c in visibleRows" :key="c.rowKey"><button class="tm-conv" :class="{'is-active':view==='chat'&&current?.id===c.id}" @click="selectRow(c)" :aria-label="'بازکردن '+c.display_name"><span class="tm-avatar" :style="avatarStyle(person(c))" x-html="avatar(person(c))" @error.capture="imageFailed(person(c))"></span><span class="tm-live" x-show="trulyOnline(person(c))" aria-label="آنلاین"></span><span class="tm-rowtext"><span class="tm-rowtitle"><strong x-text="c.display_name"></strong><time x-text="c.last_message_time||''"></time></span><span class="tm-preview" x-text="drafts[c.id] ? 'پیش‌نویس: '+drafts[c.id] : c.last_message || 'شروع گفتگو' "></span></span><span class="tm-unread" x-show="c.unread_count>0" x-text="c.unread_count"></span></button></template><div class="tm-noresults" x-show="!visibleRows.length"><span x-html="icon('search')"></span><b>گفتگویی پیدا نشد</b><p>عبارت دیگری را جستجو کن یا تب را تغییر بده.</p></div></div>
  <div class="tm-listfoot"><span class="tm-lock" x-html="icon('lock')"></span><span>گفتگوهای کاری · فقط مکتوب</span></div>
 </aside>
 <section class="tm-content" aria-label="فضای گفتگو">
  <div class="tm-empty" x-show="!current&&view==='chat'"><div class="tm-emptyicon" x-html="icon('chat')"></div><h2>گفتگو از اینجا شروع می‌شود</h2><p>یک گفتگو را انتخاب کن؛ یا در فضای شخصی برای خودت یادداشت بنویس.</p><button class="tm-primary" @click="openSelf()">رفتن به فضای شخصی <span x-html="icon('bookmark')"></span></button><span class="tm-textonly">فقط پیام مکتوب · بدون تماس و ویس</span></div>
  <template x-if="current||view==='stars'"><div class="tm-chatview">
   <header class="tm-chathead"><button class="tm-iconbtn tm-back" @click="mobileChat=false" aria-label="بازگشت به گفتگوها" x-html="icon('back')"></button><span class="tm-avatar tm-headavatar" :style="avatarStyle(view==='stars'?{id:'stars',type:'saved'}:person(current))" x-html="view==='stars'?icon('star'):avatar(person(current))" @error.capture="current&&imageFailed(person(current))"></span><button class="tm-chatperson" @click="current&&showInfo()"><h2 x-text="view==='stars'?'پیام‌های ستاره‌دار':current?.display_name"></h2><span :class="{'tm-online':view!=='stars'&&trulyOnline(person(current))}" x-text="view==='stars' ? 'دسترسی سریع به پیام‌های مهم' : current?.type==='saved' ? 'فضای شخصی شما؛ همیشه در دسترس' : current?.type==='private' ? presenceLabel(person(current)) : memberLabel(current)"></span></button><div class="tm-headtools"><button class="tm-iconbtn" @click="searchOpen=!searchOpen;if(!searchOpen)messageQuery=''" aria-label="جستجو در پیام‌ها" :class="{'is-active':searchOpen}" x-html="icon('search')"></button><button class="tm-iconbtn" x-show="current&&current.type!=='saved'&&view==='chat'" @click="showInfo()" aria-label="اطلاعات گفتگو" x-html="icon('info')"></button></div></header>
   <div class="tm-insearch" x-show="searchOpen" x-cloak><label class="tm-search"><span x-html="icon('search')"></span><input x-model="messageQuery" @input.debounce.350ms="searchMessages()" placeholder="جستجو در متن پیام‌ها…" aria-label="جستجو در متن پیام‌ها"><button @click="messageQuery='';searchOpen=false" aria-label="بستن جستجوی پیام" x-html="icon('close')"></button></label><span x-text="filteredMessages.length+' پیام'"></span></div>
   <div class="tm-messages" x-ref="messages" @click.self="menuMessage=null;reactionMessage=null">
    <button class="tm-more" x-show="hasMore&&!messageQuery&&view==='chat'" @click="loadOlder()" :disabled="loadingOlder" x-text="loadingOlder?'در حال دریافت…':'پیام‌های قدیمی‌تر'"></button>
    <div class="tm-day" x-show="filteredMessages.length"><span x-text="view==='stars'?'پیام‌های منتخب':'گفتگوهای مکتوب'"></span></div>
    <template x-for="m in filteredMessages" :key="m.id"><article class="tm-message" :class="{'is-mine':m.is_mine}" :data-message-id="m.id"><span class="tm-avatar tm-messageavatar" x-show="!m.is_mine&&current?.type==='group'" :style="avatarStyle(sender(m))" x-html="avatar(sender(m))" @error.capture="imageFailed(sender(m))"></span><div class="tm-messagecol"><div class="tm-bubble">
     <span class="tm-sender" x-show="!m.is_mine&&current?.type==='group'" :style="'color:'+avatarColor(sender(m))" x-text="m.sender_name"></span><span class="tm-forwarded" x-show="m.forwarded_from_name" x-text="'فوروارد از '+m.forwarded_from_name"></span>
     <button class="tm-quote" x-show="m.reply_to" @click="jump(m.reply_to?.id)"><b x-text="m.reply_to?.sender_name"></b><span x-text="m.reply_to?.content||'پیوست'"></span></button>
     <template x-if="m.type==='image'&&m.file_url"><button class="tm-image" @click="preview=m" aria-label="نمایش تصویر"><img :src="m.file_url" :alt="m.file_name||'تصویر پیوست'" loading="lazy"></button></template>
     <template x-if="m.type==='file'&&m.file_url"><a class="tm-file" :href="m.file_url" :download="m.file_name"><span x-html="icon('file')"></span><span><b x-text="m.file_name||'سند پیوست'"></b><small>دریافت فایل</small></span><span x-html="icon('download')"></span></a></template>
     <p class="tm-messagebody" x-html="highlight(m.content)"></p><div class="tm-msgmeta"><span x-show="isStarred(m)" class="tm-starbadge" x-html="icon('starFill')" aria-label="ستاره‌دار"></span><span x-show="m.edited_at">ویرایش‌شده</span><time x-text="m.time"></time><span class="tm-ticks" x-show="m.is_mine" x-text="m.is_read?'✓✓':'✓'" :title="m.is_read?'خوانده‌شده':'ذخیره‌شده'"></span></div>
    </div><div class="tm-reactions" x-show="m.reactions?.length"><template x-for="r in m.reactions||[]" :key="r.emoji"><button @click="react(m,r.emoji)" :class="{'is-active':r.has_reacted}" :aria-label="r.emoji+' '+r.count"><span x-text="r.emoji"></span><small x-text="r.count"></small></button></template></div>
    <div class="tm-msgactions"><button @click="replyTo(m)" title="پاسخ" aria-label="پاسخ به پیام" x-html="icon('reply')"></button><button @click="react(m,'👍')" title="پسندیدن" aria-label="پسندیدن پیام" x-html="icon('like')"></button><button @click="reactionMessage=reactionMessage===m.id?null:m.id" title="واکنش" aria-label="واکنش به پیام" x-html="icon('smile')"></button><button @click="star(m)" :title="isStarred(m)?'حذف ستاره':'ستاره‌دار کردن'" :aria-label="isStarred(m)?'حذف ستاره پیام':'ستاره‌دار کردن پیام'" :class="{'is-starred':isStarred(m)}" x-html="icon('star')"></button><button @click="showForward(m)" title="فوروارد" aria-label="فوروارد پیام" x-html="icon('forward')"></button><button @click="saveToSelf(m)" title="ذخیره در فضای شخصی" aria-label="ذخیره پیام در فضای شخصی" x-html="icon('bookmark')"></button><button x-show="m.is_mine" @click="editMessage(m)" title="ویرایش" aria-label="ویرایش پیام" x-html="icon('edit')"></button></div>
    <div class="tm-emojis" x-show="reactionMessage===m.id" x-cloak><template x-for="emoji in emojis" :key="emoji"><button @click="react(m,emoji);reactionMessage=null" :aria-label="'واکنش '+emoji" x-text="emoji"></button></template></div><button class="tm-source" x-show="view==='stars'" @click="openFromStar(m)"><span x-html="icon('chat')"></span><span x-text="m.conversation_name||'رفتن به گفتگو'"></span></button>
    </div></article></template>
    <div class="tm-chatempty" x-show="!filteredMessages.length"><span x-html="icon(view==='stars'?'star':'bookmark')"></span><h3 x-text="messageQuery?'پیامی پیدا نشد':view==='stars'?'پیام مهمت را ستاره‌دار کن':current?.type==='saved'?'این فضا برای خودت است':'اولین پیام را بنویس'"></h3><p x-text="messageQuery?'متن دیگری را جستجو کن.':current?.type==='saved'?'یادداشت بنویس، سند نگه دار یا پیام‌های دیگر را اینجا فوروارد کن.':view==='stars'?'ستارهٔ کنار هر پیام، آن را به این فهرست اضافه می‌کند.':'متن پیام خود را در پایین بنویس.'"></p></div>
   </div>
   <div class="tm-composehint" x-show="view==='chat'&&current?.can_send===false">فقط مدیران این کانال اجازهٔ ارسال پیام دارند.</div>
   <div class="tm-composer" x-show="view==='chat'&&current?.can_send!==false"><div class="tm-composecontext" x-show="replyingTo||editing"><span x-html="icon(editing?'edit':'reply')"></span><div><b x-text="editing?'ویرایش پیام':'پاسخ به '+(replyingTo?.sender_name||'')"></b><p x-text="editing?.content||replyingTo?.content||'پیوست'"></p></div><button class="tm-iconbtn" @click="cancelContext()" aria-label="لغو پاسخ یا ویرایش" x-html="icon('close')"></button></div>
    <div class="tm-attachment" x-show="attachment"><span x-html="icon('file')"></span><div><b x-text="attachment?.name"></b><small x-text="size(attachment?.size||0)"></small></div><button class="tm-iconbtn" @click="attachment=null;$refs.fileInput.value=''" aria-label="حذف پیوست" x-html="icon('close')"></button></div>
    <div class="tm-composebar"><input type="file" x-ref="fileInput" @change="pickFile($event)" accept=".png,.jpg,.jpeg,.webp,.gif,.pdf,.txt,.csv,.doc,.docx,.xls,.xlsx" hidden><button class="tm-iconbtn tm-attach" @click="$refs.fileInput.click()" aria-label="افزودن تصویر یا سند" title="تصویر و سند؛ حداکثر ۵ مگابایت" :disabled="sending||!!editing" x-html="icon('attach')"></button><textarea x-model="newMessage" maxlength="12000" x-ref="composer" @input="saveDraft();resizeComposer()" @keydown.enter="if(!$event.shiftKey&&!$event.isComposing){$event.preventDefault();send()}" rows="1" placeholder="پیام خود را بنویس…" aria-label="متن پیام"></textarea><button class="tm-send" @click="send()" :disabled="sending||(!newMessage.trim()&&!attachment)" :aria-label="editing?'ذخیره ویرایش پیام':'ارسال پیام متنی'" x-html="icon(editing?'check':'send')"></button></div><div class="tm-composehint"><span>فقط پیام مکتوب</span><span>Enter ارسال · Shift + Enter خط جدید</span></div>
   </div>
  </div></template>
 </section>
 <div class="tm-overlay" x-show="dialog" x-cloak @click.self="closeDialog()"><section class="tm-modal" role="dialog" aria-modal="true" :aria-label="dialogTitle"><div class="tm-modalhead"><div><h2 x-text="dialogTitle"></h2><p x-text="dialog==='forward'?'گفتگوی مقصد را انتخاب کن.':dialog==='info'?'مشخصات و اعضای این گفتگو':'گفتگوی شخصی، گروه یا کانال بساز.'"></p></div><button class="tm-iconbtn" @click="closeDialog()" aria-label="بستن پنجره" x-html="icon('close')"></button></div>
  <template x-if="dialog==='forward'"><div class="tm-modalbody"><button class="tm-target tm-target--saved" @click="forwardTo(selfConversation.id)" aria-label="فوروارد به فضای شخصی"><span class="tm-avatar tm-avatar--saved" x-html="icon('bookmark')"></span><span><b>فضای شخصی</b><small>ذخیره برای خودم</small></span><span x-html="icon('pin')"></span></button><label class="tm-search"><span x-html="icon('search')"></span><input x-model="targetQuery" aria-label="جستجوی مقصد فوروارد" placeholder="جستجوی مقصد…"></label><div class="tm-targetlist"><template x-for="c in forwardTargets" :key="c.id"><button class="tm-target" @click="forwardTo(c.id)"><span class="tm-avatar" :style="avatarStyle(person(c))" x-html="avatar(person(c))"></span><b x-text="c.display_name"></b><span x-html="icon('forward')"></span></button></template><p class="tm-noresults" x-show="!forwardTargets.length">مقصد دیگری پیدا نشد.</p></div></div></template>
  <template x-if="dialog==='create'"><div class="tm-modalbody"><div class="tm-create-tabs"><template x-for="t in [{id:'private',label:'شخصی'},{id:'group',label:'گروه'},{id:'channel',label:'کانال'}]" :key="t.id"><button @click="createType=t.id" :class="{'is-active':createType===t.id}" x-text="t.label"></button></template></div><label class="tm-field" x-show="createType!=='private'"><span x-text="createType==='group'?'نام گروه':'نام کانال'"></span><input x-model="newName" maxlength="80" placeholder="یک نام مشخص انتخاب کن…" aria-label="نام گفتگو"></label><p class="tm-modalhint" x-text="createType==='private'?'همکار موردنظر را انتخاب کن.':'اعضای گفتگو را انتخاب کن.'"></p><div class="tm-targetlist"><template x-for="u in otherUsers" :key="u.id"><button class="tm-target" @click="createType==='private'?startPrivate(u.id):toggleMember(u.id)"><span class="tm-avatar" :style="avatarStyle(u)" x-html="avatar(u)"></span><b x-text="u.name"></b><span class="tm-check" x-show="createType!=='private'" :class="{'is-selected':selectedMembers.includes(u.id)}" x-html="selectedMembers.includes(u.id)?icon('check'):''"></span></button></template></div><button x-show="createType!=='private'" class="tm-primary tm-full" @click="createConversation()" :disabled="creating||!newName.trim()||!selectedMembers.length" x-text="creating?'در حال ساخت…':createType==='group'?'ایجاد گروه':'ایجاد کانال'"></button></div></template>
  <template x-if="dialog==='info'"><div class="tm-modalbody"><div class="tm-profile"><span class="tm-avatar tm-avatar--large" :style="avatarStyle(person(current))" x-html="avatar(person(current))"></span><h3 x-text="current?.display_name"></h3><p x-text="current?.type==='saved'?'فقط برای خودت؛ یادداشت و پیام‌های ذخیره‌شده':current?.type==='private'?presenceLabel(person(current)):memberLabel(current)"></p></div><div class="tm-targetlist"><template x-for="u in conversationUsers" :key="u.id"><div class="tm-target"><span class="tm-avatar" :style="avatarStyle(u)" x-html="avatar(u)"></span><span><b x-text="u.name"></b><small x-text="presenceLabel(u)"></small></span></div></template></div></div></template>
 </section></div>
 <div class="tm-overlay tm-lightbox" x-show="preview" x-cloak @click.self="preview=null"><button class="tm-iconbtn" @click="preview=null" aria-label="بستن تصویر" x-html="icon('close')"></button><img :src="preview?.file_url||''" :alt="preview?.file_name||'پیوست'"></div>
 <div class="tm-toast" role="status" x-show="notice" x-cloak x-text="notice"></div>
</section></div>

